mapper.select:
SELECT tc.*, tu.user_name, CASE WHEN tc.target_type = 1 THEN u.avatar WHEN tc.target_type = 2 THEN NULL ELSE NULL END AS avatar,
CASE WHEN tc.target_type = 1 THEN u.user_name WHEN tc.target_type = 2 THEN ts.`name` ELSE NULL END AS `name` FROM travel_complaint tc LEFT JOIN tb_user u ON tc.target_id = u.user_id LEFT JOIN tb_user tu ON tc.user_id = tu.user_id LEFT JOIN travel_shop ts ON tc.target_id = ts.id
and tc.user_id = #{param.userId}
and tc.target_type = #{param.targetType}
and tc.status = #{param.status}
and tc.reason like concat('%', #{param.reason} ,'%')
ORDER BY tc.create_time DESC
